import CoreGraphics
import Foundation
import Testing
import GlyphRecognitionImages
@testable import GlyphRecognition

/// Our own floating window over the right side of the slot row, from the
/// frames in `Fixtures/WindowCover`. The expected answers are the
/// visible screens, read by eye; nothing here is generated by the reader.
@Suite("Slot strip beside our own window")
struct WindowCoverTests {
    static func band(_ file: String) throws -> FrameTopBand {
        try CxxSlotStripTests.band(ReferenceData.fixturesDirectory.appendingPathComponent("WindowCover/\(file)"))
    }

    /// The band flipped left to right: the window over the row's left side.
    static func mirrored(_ band: FrameTopBand) throws -> FrameTopBand {
        let image = band.image
        var pixels = [UInt8](repeating: 0, count: image.pixels.count)
        for y in 0..<image.height {
            for x in 0..<image.width {
                let source = (y * image.width + (image.width - 1 - x)) * 3
                let target = (y * image.width + x) * 3
                pixels[target] = image.pixels[source]
                pixels[target + 1] = image.pixels[source + 1]
                pixels[target + 2] = image.pixels[source + 2]
            }
        }
        return FrameTopBand(image: try ColorImage(width: image.width, height: image.height, pixels: pixels),
                            frameHeight: band.frameHeight)
    }

    /// The input frames under the window: the visible indicators' slots in
    /// the four-slot row, the visible highlight's slot, if one shows. The
    /// `cover-` frames are the video scaled back to the 603 px capture; the
    /// `native-` frames are the video's own 602 px, unscaled.
    static let inputFrames: [(file: String, slots: [Int], highlight: Int?)] = [
        ("cover-0211.png", [0, 1], 0),
        ("cover-0247.png", [0, 1], 1),
        ("cover-0281.png", [0, 1], nil),
        ("cover-0331.png", [0, 1], nil),
        ("native-0211.png", [0, 1], 0),
        ("native-0281.png", [0, 1], nil),
    ]

    /// The window's inner side, as a fraction of the width: column 306 of
    /// both the 603 px and the 602 px frames.
    static let windowSide = 306.0 / 602.5

    /// The frame redrawn at `width` by `height`, smoothly interpolated, as a
    /// recording scaled to another capture size is.
    static func resized(_ file: String, width: Int, height: Int) throws -> FrameTopBand {
        let source = try EdgeTab.image("WindowCover/\(file)")
        let context = try #require(CGContext(data: nil, width: width, height: height, bitsPerComponent: 8,
                                             bytesPerRow: width * 4, space: CGColorSpaceCreateDeviceRGB(),
                                             bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue))
        context.interpolationQuality = .high
        context.draw(source, in: CGRect(x: 0, y: 0, width: width, height: height))
        return try ImageDecoder.topBand(try #require(context.makeImage()))
    }

    /// Each window fixture at its own size and at the other sizes it must
    /// read at: the 603 px capture, the 602 px video and a 562 px capture.
    static func sizes(_ file: String) throws -> [(label: String, band: FrameTopBand)] {
        var bands = [(file, try band(file))]
        for (width, height) in [(603, 1311), (602, 1310), (562, 1218)] {
            let original = bands[0].1.image.width
            guard width != original else { continue }
            bands.append(("\(file) at \(width)x\(height)", try resized(file, width: width, height: height)))
        }
        return bands
    }

    /// The reading every input frame gives: our window over the right of the
    /// row from its inner side, the countdown beside it, and the visible
    /// indicators on the given slots.
    static func expectInput(_ observation: SlotStripObservation, width: Int, slots: [Int], highlight: Int?,
                            mirrored: Bool, _ label: String) throws {
        let comment = Comment(rawValue: label)
        // The full reading still fails: the hidden slots are unknown.
        #expect(throws: SlotStripRejection.self, comment) { try observation.reading.get() }
        let cover = try #require(observation.cover, comment)
        let tolerance = 3.0 / Double(width)
        if mirrored {
            #expect(cover.side == .left && cover.coveredFrom == 0, comment)
            #expect(abs(cover.coveredTo - (1 - windowSide)) <= tolerance, comment)
        } else {
            #expect(cover.side == .right && cover.coveredTo == 1, comment)
            #expect(abs(cover.coveredFrom - windowSide) <= tolerance, comment)
        }
        #expect(cover.hasPartialInputTimerBar, comment)
        let row = try #require(cover.row, comment)
        #expect(row.markerCentersX.count == 2, comment)
        let resolution = try #require(row.resolved(slotCount: 4), comment)
        #expect(resolution.slotIndices == (mirrored ? slots.map { 3 - $0 }.reversed() : slots), comment)
        #expect(resolution.highlightedIndex == (mirrored ? highlight.map { 3 - $0 } : highlight), comment)
    }

    @Test("The window over the right of the row leaves the visible indicators and the countdown")
    func inputBesideWindow() throws {
        let reader = SlotStripReader()
        for (file, slots, highlight) in Self.inputFrames {
            let band = try Self.band(file)
            #expect(!reader.hasTimerBar(band), Comment(rawValue: file))
            try Self.expectInput(reader.observe(band), width: band.image.width, slots: slots, highlight: highlight,
                                 mirrored: false, file)
        }
    }

    @Test("The same frames mirrored read the window on the left")
    func mirroredInput() throws {
        let reader = SlotStripReader()
        for (file, slots, highlight) in Self.inputFrames {
            let band = try Self.mirrored(Self.band(file))
            try Self.expectInput(reader.observe(band), width: band.image.width, slots: slots, highlight: highlight,
                                 mirrored: true, file)
        }
    }

    @Test("Every window fixture reads the same at the capture's, the video's and a third size, mirrored too")
    func everySize() throws {
        let reader = SlotStripReader()
        for (file, slots, highlight) in Self.inputFrames {
            for (label, band) in try Self.sizes(file) {
                try Self.expectInput(reader.observe(band), width: band.image.width, slots: slots,
                                     highlight: highlight, mirrored: false, label)
                try Self.expectInput(reader.observe(Self.mirrored(band)), width: band.image.width, slots: slots,
                                     highlight: highlight, mirrored: true, "mirrored \(label)")
            }
        }
        for (label, band) in try Self.sizes("cover-0381.png") {
            let observation = reader.observe(band)
            #expect(observation.cover?.hasPartialInputTimerBar != true && observation.cover?.row == nil,
                    Comment(rawValue: label))
        }
        for file in ["cover-0151.png", "cover-0191.png"] {
            for (label, band) in try Self.sizes(file) {
                #expect(reader.observe(band).cover == nil, Comment(rawValue: label))
            }
        }
    }

    @Test("The result screen beside the window has no countdown and no indicator row")
    func resultBesideWindow() throws {
        let observation = SlotStripReader().observe(try Self.band("cover-0381.png"))
        #expect(throws: SlotStripRejection.self) { try observation.reading.get() }
        #expect(observation.cover?.hasPartialInputTimerBar != true)
        #expect(observation.cover?.row == nil)
    }

    @Test("Frames without the window over the row find none")
    func noWindow() throws {
        let reader = SlotStripReader()
        // The presentation with the window tucked into a tab at the right
        // edge, and the first input frame before the window moved over.
        let presentation = reader.observe(try Self.band("cover-0151.png"))
        #expect(presentation.cover == nil)
        let reading = try presentation.reading.get()
        #expect(reading.slotCount == 4 && reading.highlightedIndex == 1 && !reading.hasInputTimerBar)
        let input = reader.observe(try Self.band("cover-0191.png"))
        #expect(input.cover == nil)
        let inputReading = try input.reading.get()
        #expect(inputReading.slotCount == 4 && inputReading.highlightedIndex == 0 && inputReading.hasInputTimerBar)
    }

    @Test("No other fixture is read as our window beside the row",
          arguments: CxxSlotStripTests.fixtureFolders.filter { $0 != "WindowCover" })
    func otherFixtures(folder: String) throws {
        let reader = SlotStripReader()
        for url in try CxxSlotStripTests.fixtureImages(in: folder) {
            let band = try CxxSlotStripTests.band(url)
            #expect(reader.observe(band).cover == nil, Comment(rawValue: "\(folder)/\(url.lastPathComponent)"))
        }
    }

    @Test("The edge tab over any fixture is not read as our window beside the row",
          arguments: EdgeTab.Side.allCases)
    func edgeTab(side: EdgeTab.Side) throws {
        let reader = SlotStripReader()
        for (label, image) in try EdgeTab.frames() where !label.hasPrefix("WindowCover/") {
            let band = try ImageDecoder.topBand(EdgeTab.draw(image, side: side))
            #expect(reader.observe(band).cover == nil, Comment(rawValue: label))
        }
    }

    @Test("Visible indicators are placed in rows of two to five slots on either side")
    func resolution() {
        let pitch = GameUILayout().slotCenterPitch
        func center(_ index: Int, of count: Int) -> Double { 0.5 + (Double(index) - Double(count - 1) / 2) * pitch }
        for count in 2...5 {
            for visible in 1..<count {
                // The window over the right: slots 0..<visible show.
                let rightFrom = (center(visible - 1, of: count) + center(visible, of: count)) / 2
                let right = PartialSlotStripReading(
                    markerCentersX: (0..<visible).map { center($0, of: count) + 0.01 },
                    highlightedMarker: visible - 1, coveredFrom: rightFrom, coveredTo: 1)
                #expect(right.resolved(slotCount: count)
                        == .init(slotIndices: Array(0..<visible), highlightedIndex: visible - 1))
                // The window over the left: the last `visible` slots show.
                let shown = Array((count - visible)..<count)
                let leftTo = (center(count - visible - 1, of: count) + center(count - visible, of: count)) / 2
                let left = PartialSlotStripReading(
                    markerCentersX: shown.map { center($0, of: count) - 0.01 },
                    highlightedMarker: nil, coveredFrom: 0, coveredTo: leftTo)
                #expect(left.resolved(slotCount: count) == .init(slotIndices: shown, highlightedIndex: nil))
            }
        }
    }

    @Test("Indicators that fit no row of the known count are not placed")
    func ambiguousResolution() {
        // Two indicators at the four-slot row's first two places, with only
        // the right third covered: slot 2 would show, so this is not a
        // four-slot row seen beside the window.
        let narrow = PartialSlotStripReading(markerCentersX: [0.26, 0.42], highlightedMarker: 0,
                                             coveredFrom: 0.7, coveredTo: 1)
        #expect(narrow.resolved(slotCount: 4) == nil)
        #expect(narrow.resolved(slotCount: 3) == nil)
        // Off the grid, more markers than slots, a zero count.
        let offGrid = PartialSlotStripReading(markerCentersX: [0.32], highlightedMarker: nil,
                                              coveredFrom: 0.5, coveredTo: 1)
        #expect(offGrid.resolved(slotCount: 4) == nil)
        let many = PartialSlotStripReading(markerCentersX: [0.26, 0.42, 0.58], highlightedMarker: nil,
                                           coveredFrom: 0.7, coveredTo: 1)
        #expect(many.resolved(slotCount: 2) == nil)
        #expect(many.resolved(slotCount: 0) == nil)
        // Two markers on one slot.
        let twice = PartialSlotStripReading(markerCentersX: [0.25, 0.27], highlightedMarker: nil,
                                            coveredFrom: 0.5, coveredTo: 1)
        #expect(twice.resolved(slotCount: 4) == nil)
    }
}
